package controlplane_test

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"net"
	"os"
	"testing"
	"time"

	"cascade/controlplane"
	pb "cascade/gen/cascadepb"

	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials"
	"google.golang.org/grpc/test/bufconn"
)

// Loads the dev CA/server cert pair generated by the setup script.
// Skips (not fails) if certs aren't present -- this test requires
// generated material that's deliberately NOT committed (private key),
// so a fresh clone without running the cert-gen step should skip
// cleanly, not error out.
func loadTestCerts(t *testing.T) (serverCert tls.Certificate, caPool *x509.CertPool) {
	t.Helper()
	const certDir = "../../certs"
	certPath := certDir + "/server-cert.pem"
	keyPath := certDir + "/server-key.pem"
	caPath := certDir + "/ca-cert.pem"

	if _, err := os.Stat(certPath); os.IsNotExist(err) {
		t.Skip("certs/ not generated -- run the cert-gen script first (see TLS setup docs)")
	}

	cert, err := tls.LoadX509KeyPair(certPath, keyPath)
	if err != nil {
		t.Fatalf("load server cert/key: %v", err)
	}
	caBytes, err := os.ReadFile(caPath)
	if err != nil {
		t.Fatalf("read CA cert: %v", err)
	}
	pool := x509.NewCertPool()
	if !pool.AppendCertsFromPEM(caBytes) {
		t.Fatal("failed to parse CA cert")
	}
	return cert, pool
}

func TestTLS_ClientRejectsConnectionWithoutTrustingCA(t *testing.T) {
	serverCert, _ := loadTestCerts(t)

	lis := bufconn.Listen(1024 * 1024)
	creds := credentials.NewServerTLSFromCert(&serverCert)
	grpcServer := grpc.NewServer(grpc.Creds(creds))
	pb.RegisterCascadeControlPlaneServer(grpcServer, controlplane.NewServer(controlplane.RealClock{}, 5*time.Second))
	go grpcServer.Serve(lis)
	t.Cleanup(grpcServer.Stop)

	// Client with an EMPTY trust pool -- should reject the server's cert
	// since it doesn't trust the CA that signed it. This is the actual
	// security property TLS is providing: proves a MITM presenting an
	// untrusted cert gets rejected, not silently trusted.
	emptyPool := x509.NewCertPool()
	badCreds := credentials.NewTLS(&tls.Config{RootCAs: emptyPool, ServerName: "localhost"})

	conn, err := grpc.NewClient("passthrough:///bufnet",
		grpc.WithContextDialer(func(ctx context.Context, _ string) (net.Conn, error) { return lis.DialContext(ctx) }),
		grpc.WithTransportCredentials(badCreds),
	)
	if err != nil {
		t.Fatalf("dial itself shouldn't fail (TLS handshake happens on first RPC): %v", err)
	}
	defer conn.Close()

	client := pb.NewCascadeControlPlaneClient(conn)
	_, err = client.ListTopics(context.Background(), &pb.Empty{})
	if err == nil {
		t.Fatal("expected RPC to fail: client does not trust the CA that signed the server's cert")
	}
	t.Logf("correctly rejected untrusted server cert: %v", err)
}

func TestTLS_ClientAcceptsConnectionWithCorrectCA(t *testing.T) {
	serverCert, caPool := loadTestCerts(t)

	lis := bufconn.Listen(1024 * 1024)
	creds := credentials.NewServerTLSFromCert(&serverCert)
	grpcServer := grpc.NewServer(grpc.Creds(creds))
	pb.RegisterCascadeControlPlaneServer(grpcServer, controlplane.NewServer(controlplane.RealClock{}, 5*time.Second))
	go grpcServer.Serve(lis)
	t.Cleanup(grpcServer.Stop)

	goodCreds := credentials.NewTLS(&tls.Config{RootCAs: caPool, ServerName: "localhost"})
	conn, err := grpc.NewClient("passthrough:///bufnet",
		grpc.WithContextDialer(func(ctx context.Context, _ string) (net.Conn, error) { return lis.DialContext(ctx) }),
		grpc.WithTransportCredentials(goodCreds),
	)
	if err != nil {
		t.Fatalf("dial failed: %v", err)
	}
	defer conn.Close()

	client := pb.NewCascadeControlPlaneClient(conn)
	_, err = client.ListTopics(context.Background(), &pb.Empty{})
	if err != nil {
		t.Fatalf("expected RPC to succeed with correct CA trust, got: %v", err)
	}
}